*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#102d32;color:#f5f2e8;font-family:'DM Sans',sans-serif}button{font:inherit;color:inherit;border:0;cursor:pointer}#game-shell{position:relative;width:100%;height:100%;min-height:100dvh;overflow:hidden;background:#84b38c;isolation:isolate}#world{position:absolute;inset:0;width:100%;height:100%;display:block;touch-action:none}.vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,rgba(8,27,30,.38),transparent 22%,transparent 62%,rgba(8,25,29,.26)),radial-gradient(ellipse at center,transparent 47%,rgba(8,27,30,.17) 100%);z-index:1}.topbar{position:absolute;z-index:3;inset:0 0 auto;height:74px;padding:0 38px;display:flex;align-items:center;justify-content:space-between;background:linear-gradient(180deg,rgba(5,24,29,.55),transparent)}.brand{display:flex;align-items:center;gap:11px;background:none;letter-spacing:.18em;font:700 12px 'Outfit',sans-serif}.brand-mark{display:grid;place-items:center;width:30px;height:30px;border:1px solid rgba(246,239,216,.7);border-radius:50%;font:600 16px Georgia;color:#f4df9b;letter-spacing:0}.top-center{position:absolute;left:50%;transform:translateX(-50%);display:flex;gap:12px;align-items:center;font-size:9px;letter-spacing:.14em;color:rgba(255,255,255,.82);font-weight:700}.top-center i{height:13px;width:1px;background:rgba(255,255,255,.45)}.weather-dot,.eyebrow-dot{width:7px;height:7px;border-radius:50%;background:#c9db8a;box-shadow:0 0 10px #d4df8b}.icon-btn{width:36px;height:36px;border:1px solid rgba(255,255,255,.48);background:rgba(13,40,38,.22);border-radius:50%;font-size:20px;line-height:1}.hud-left,.hud-right{z-index:2;position:absolute;top:104px}.hud-left{left:38px;max-width:290px}.quest-card{padding:17px 19px 14px;background:rgba(14,37,35,.76);border:1px solid rgba(255,255,255,.17);backdrop-filter:blur(10px);box-shadow:0 10px 32px rgba(13,33,27,.12)}.eyebrow{display:flex;align-items:center;gap:8px;font-size:9px;letter-spacing:.16em;font-weight:700;color:#d9dcae}.eyebrow-dot{width:5px;height:5px}.quest-title{font:600 19px 'Outfit',sans-serif;margin-top:12px;letter-spacing:.005em}.quest-sub{font-size:11px;color:rgba(245,242,232,.66);margin-top:5px}.progress-line{height:2px;background:rgba(255,255,255,.2);margin-top:18px}.progress-line span{display:block;height:100%;width:0;background:#d7dc9f;transition:width .3s}.quest-foot{display:flex;justify-content:space-between;margin-top:8px;color:rgba(245,242,232,.61);font-size:8px;letter-spacing:.12em;font-weight:700}.location-card{display:flex;gap:11px;align-items:center;margin-top:12px;padding:10px 13px;background:rgba(17,45,43,.63);backdrop-filter:blur(8px);width:max-content;max-width:100%}.pin-icon{color:#e6d798;font-size:15px}.location-name{font:700 9px 'Outfit',sans-serif;letter-spacing:.16em}.location-detail{font-size:9px;color:rgba(245,242,232,.65);margin-top:3px}.hud-right{right:38px;display:flex;align-items:flex-end;flex-direction:column;gap:10px}.minimap-frame{position:relative;width:162px;height:162px;border-radius:50%;padding:5px;background:rgba(20,46,43,.7);border:1px solid rgba(255,255,255,.45);box-shadow:0 8px 30px rgba(10,30,27,.2);backdrop-filter:blur(7px)}#minimap{width:100%;height:100%;border-radius:50%;display:block}.map-compass{position:absolute;top:10px;left:50%;transform:translateX(-50%);font:700 9px 'Outfit';color:#fff;text-shadow:0 1px 5px #152b25}.map-label{position:absolute;bottom:12px;left:0;right:0;text-align:center;font-size:7px;letter-spacing:.16em;font-weight:700;text-shadow:0 1px 5px #152b25}.map-label span{font-size:11px;margin-left:4px}.stats-row{display:flex;gap:6px}.stat-chip{min-width:76px;padding:8px 10px;background:rgba(14,37,35,.69);border:1px solid rgba(255,255,255,.15);display:grid;grid-template-columns:16px 1fr;align-items:center}.stat-icon{grid-row:span 2;color:#e3d694;font-size:13px}.stat-chip span:nth-child(2){font:600 14px 'Outfit';line-height:1}.stat-chip small{grid-column:2;font-size:7px;letter-spacing:.13em;color:rgba(245,242,232,.58);margin-top:3px}.toast{position:absolute;left:50%;top:24%;transform:translate(-50%,-10px);z-index:5;opacity:0;pointer-events:none;background:rgba(15,42,37,.9);padding:11px 17px;border:1px solid rgba(236,221,157,.45);font-size:11px;letter-spacing:.04em;transition:all .35s}.toast.show{opacity:1;transform:translate(-50%,0)}.toast span:first-child{color:#e9d889;margin-right:8px}.center-prompt{position:absolute;z-index:2;left:50%;bottom:22%;transform:translateX(-50%);font-size:11px;letter-spacing:.08em;text-shadow:0 1px 5px #18342d}.bottom-hint{position:absolute;z-index:2;bottom:25px;left:50%;transform:translateX(-50%);color:rgba(255,255,255,.8);font-size:8px;letter-spacing:.14em;font-weight:700;white-space:nowrap;text-shadow:0 1px 8px #18342d}.keycap{padding:5px 7px;border:1px solid rgba(255,255,255,.55);border-radius:3px;font-size:8px;margin-right:4px}.hint-divider{margin:0 10px;color:#eddf9f}.touch-controls{display:none;position:absolute;z-index:4;bottom:max(24px,env(safe-area-inset-bottom));left:0;right:0;align-items:flex-end;justify-content:space-between;padding:0 25px;pointer-events:none}.joystick{width:116px;height:116px;position:relative;pointer-events:auto;touch-action:none}.joy-ring{position:absolute;inset:0;border-radius:50%;background:rgba(11,35,34,.27);border:1px solid rgba(255,255,255,.48);backdrop-filter:blur(5px)}.joy-knob{position:absolute;width:49px;height:49px;border-radius:50%;left:33.5px;top:33.5px;background:rgba(235,231,201,.79);border:1px solid white;box-shadow:0 4px 15px rgba(0,0,0,.2)}.touch-actions{display:flex;gap:12px;pointer-events:auto;align-items:flex-end}.action-btn{width:62px;height:62px;border-radius:50%;border:1px solid rgba(255,255,255,.6);background:rgba(11,35,34,.32);backdrop-filter:blur(5px);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:0;touch-action:none}.action-btn span{font:500 24px 'Outfit';line-height:1}.action-btn small{font-size:7px;letter-spacing:.12em}.sprint-btn{width:52px;height:52px;margin-bottom:3px;background:rgba(219,201,133,.34)}.sprint-btn span{font-size:21px}.overlay{position:absolute;inset:0;z-index:8;display:flex;align-items:center;background:linear-gradient(90deg,rgba(7,26,28,.91) 0%,rgba(9,30,30,.81) 39%,rgba(8,28,30,.12) 76%,rgba(8,27,29,.12) 100%);transition:opacity .55s,visibility .55s}.overlay.hidden{opacity:0;visibility:hidden;pointer-events:none}.menu-backdrop{position:absolute;inset:0;background:linear-gradient(0deg,rgba(8,26,27,.24),transparent 32%),linear-gradient(90deg,rgba(8,27,29,.24),transparent 75%);pointer-events:none}.menu-content{position:relative;margin-left:clamp(34px,10.5vw,154px);width:min(390px,calc(100vw - 48px));padding:16px 0;animation:arrive .7s both}.menu-kicker{display:flex;align-items:center;gap:10px;color:#dcdba9;font-size:8px;letter-spacing:.23em;font-weight:700}.kicker-line{width:21px;height:1px;background:#d7d59e}.menu-content h1{font:600 clamp(54px,6vw,78px)/.87 'Outfit',sans-serif;letter-spacing:-.055em;margin:27px 0 17px}.menu-content h1 em{font-weight:400;color:#d8d694}.menu-copy{font-size:12px;line-height:1.75;color:rgba(249,246,233,.69);margin:0 0 25px}.mode-heading{display:flex;justify-content:space-between;color:rgba(246,243,231,.69);font-size:8px;letter-spacing:.16em;font-weight:700;margin-bottom:9px}.mode-count{color:rgba(246,243,231,.39)}.mode-list{display:flex;flex-direction:column;gap:5px}.mode-card{width:100%;height:58px;display:flex;align-items:center;text-align:left;padding:0 13px;background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.13);transition:.2s}.mode-card:hover,.mode-card.selected{background:rgba(217,215,160,.12);border-color:rgba(225,219,162,.64)}.mode-icon{font:500 19px 'Outfit';color:#d8d694;width:35px}.mode-text{display:flex;flex-direction:column;gap:4px;flex:1}.mode-text strong{font:600 12px 'Outfit';letter-spacing:.02em}.mode-text small{color:rgba(246,243,231,.58);font-size:9px}.mode-arrow{font-size:14px;color:#e3dfb2;opacity:0;transition:.2s}.mode-card.selected .mode-arrow{opacity:1}.play-button{display:flex;align-items:center;justify-content:space-between;width:100%;height:48px;margin-top:14px;padding:0 16px;background:#d8d79b;color:#1b332f;font:700 9px 'Outfit';letter-spacing:.14em;transition:background .2s,transform .2s}.play-button span:last-child{font-size:17px}.play-button:hover{background:#eeebba;transform:translateY(-1px)}.menu-footer{margin-top:18px;text-align:center;font-size:7px;letter-spacing:.18em;color:rgba(247,243,231,.42)}.menu-footer span{padding:0 7px;color:#dcd89c}.menu-side-note{position:absolute;right:31px;bottom:26px;writing-mode:vertical-rl;font-size:8px;letter-spacing:.2em;color:rgba(255,255,255,.64)}.pause-button{display:none;position:absolute;z-index:4;right:38px;top:79px;width:33px;height:33px;border-radius:50%;border:1px solid rgba(255,255,255,.45);background:rgba(13,40,38,.42);font-size:13px}.pause-panel{position:absolute;inset:0;z-index:7;display:none;place-items:center;background:rgba(6,23,26,.54);backdrop-filter:blur(7px)}.pause-panel.visible{display:grid}.pause-box{width:min(340px,calc(100vw - 42px));padding:30px;background:rgba(17,45,43,.94);border:1px solid rgba(255,255,255,.2);box-shadow:0 24px 70px #081c1c;text-align:center}.pause-box .eyebrow{justify-content:center}.pause-box h2{font:600 31px 'Outfit';margin:21px 0 4px}.pause-box p{font-size:12px;color:rgba(255,255,255,.6);margin:0 0 20px}.pause-box .play-button{margin-top:0}.text-button{background:none;color:rgba(245,242,232,.62);font-size:8px;letter-spacing:.16em;margin-top:16px;padding:8px}.mode-banner{position:absolute;z-index:3;top:83px;left:50%;transform:translate(-50%,-8px);opacity:0;pointer-events:none;color:#f1edcf;background:rgba(12,39,37,.76);border:1px solid rgba(255,255,255,.2);padding:8px 13px;font-size:8px;letter-spacing:.14em;transition:.4s}.mode-banner.show{opacity:1;transform:translate(-50%,0)}@keyframes arrive{from{opacity:0;transform:translateY(12px)}to{opacity:1;transform:translateY(0)}}
@media(max-width:760px){.topbar{height:58px;padding:0 18px}.brand{font-size:10px;gap:8px}.brand-mark{width:26px;height:26px;font-size:14px}.top-center{font-size:7px;gap:7px}.top-center i{height:10px}.icon-btn{width:31px;height:31px}.hud-left{left:15px;top:70px;max-width:min(235px,58vw)}.quest-card{padding:12px 13px 10px}.quest-title{font-size:15px;margin-top:8px}.quest-sub{font-size:9px}.progress-line{margin-top:12px}.quest-foot{font-size:7px}.location-card{margin-top:7px;padding:8px 10px}.location-name{font-size:8px}.location-detail{font-size:8px}.hud-right{top:71px;right:14px;gap:6px}.minimap-frame{width:114px;height:114px;padding:4px}.map-compass{top:7px;font-size:7px}.map-label{bottom:8px;font-size:6px}.stats-row{gap:4px}.stat-chip{min-width:53px;padding:6px 6px;grid-template-columns:13px 1fr}.stat-icon{font-size:10px}.stat-chip span:nth-child(2){font-size:11px}.stat-chip small{font-size:6px}.bottom-hint{display:none}.touch-controls{display:flex}.pause-button{display:block;right:16px;top:64px;width:30px;height:30px}.menu-content{margin-left:clamp(25px,9vw,62px);width:min(355px,calc(100vw - 50px));padding:12px 0}.menu-content h1{font-size:clamp(52px,12vw,69px);margin:22px 0 12px}.menu-copy{font-size:11px;margin-bottom:19px}.mode-card{height:52px}.menu-side-note{display:none}.menu-footer{margin-top:13px}.overlay{background:linear-gradient(90deg,rgba(7,26,28,.93) 0%,rgba(9,30,30,.86) 66%,rgba(8,28,30,.45) 100%)}.toast{top:31%;white-space:nowrap}}
@media(max-height:700px) and (min-width:761px){.menu-content h1{font-size:59px;margin:17px 0 11px}.menu-copy{margin-bottom:17px}.mode-card{height:51px}.menu-content{transform:scale(.92);transform-origin:left center}}
@media(max-height:650px){.menu-content{transform:scale(.82);transform-origin:left center}.overlay{align-items:center}}

import * as THREE from 'three';

const canvas = document.querySelector('#world');
const renderer = new THREE.WebGLRenderer({canvas, antialias:true, powerPreference:'high-performance'});
renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 1.65));
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.05;
const scene = new THREE.Scene();
scene.background = new THREE.Color('#a7d2c2');
scene.fog = new THREE.FogExp2('#a7d2c2', 0.0037);
const camera = new THREE.PerspectiveCamera(54, innerWidth/innerHeight, .1, 650);
const clock = new THREE.Clock();
const world = new THREE.Group(); scene.add(world);

const hemi = new THREE.HemisphereLight('#e5f4e3','#4f6951',2.05); scene.add(hemi);
const sun = new THREE.DirectionalLight('#fff0c8',3.3); sun.position.set(-75,110,40); sun.castShadow=true;
sun.shadow.mapSize.set(1536,1536); sun.shadow.camera.left=-115; sun.shadow.camera.right=115; sun.shadow.camera.top=115; sun.shadow.camera.bottom=-115; sun.shadow.bias=-.0002; scene.add(sun);
const fill = new THREE.DirectionalLight('#9dd4db',.65); fill.position.set(65,35,-90); scene.add(fill);

const mat=(color,roughness=.85)=>new THREE.MeshStandardMaterial({color,roughness});
const grassMat=mat('#688d58');
const playerMats={coat:mat('#d6a957'), dark:mat('#334947'), skin:mat('#eac29a'), pack:mat('#506859'), trim:mat('#f2dfaa')};
const rand=(a,b)=>a+Math.random()*(b-a);
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
const smooth=(a,b,x)=>{const t=clamp((x-a)/(b-a),0,1);return t*t*(3-2*t)};
function heightAt(x,z){
  const r=Math.hypot(x,z);
  const edge=smooth(136,101,r);
  const hills=2.2*Math.sin(x*.038+z*.016)*Math.cos(z*.035-x*.012)+1.2*Math.sin(z*.075+x*.03);
  const mound=8*Math.exp(-((x+44)**2+(z+30)**2)/1500)+5.5*Math.exp(-((x-40)**2+(z-38)**2)/1100)+3.7*Math.exp(-((x-8)**2+(z+72)**2)/900);
  const valley=-1.8*Math.exp(-((x-2)**2+(z-15)**2)/400);
  return -3.2 + edge*(4.4+hills+mound+valley);
}
function groundColor(h,x,z){
  const c=new THREE.Color();
  if(h>7)c.set('#7a8e70');
  else if(h>4)c.set('#7b996c');
  else if(h>1.3)c.set('#76985f');
  else c.set('#71925b');
  const noise=Math.sin(x*.31+z*.2)*Math.cos(z*.29-x*.11)*.035;
  c.offsetHSL(0,0,noise);
  return c;
}
const groundGeo=new THREE.PlaneGeometry(280,280,150,150); groundGeo.rotateX(-Math.PI/2);
const pos=groundGeo.attributes.position; const colors=[];
for(let i=0;i<pos.count;i++){
  const x=pos.getX(i), z=pos.getZ(i), h=heightAt(x,z); pos.setY(i,h);
  const c=groundColor(h,x,z); colors.push(c.r,c.g,c.b);
}
groundGeo.setAttribute('color',new THREE.Float32BufferAttribute(colors,3)); groundGeo.computeVertexNormals();
const ground=new THREE.Mesh(groundGeo,new THREE.MeshStandardMaterial({vertexColors:true,roughness:1})); ground.receiveShadow=true; world.add(ground);
const ocean=new THREE.Mesh(new THREE.PlaneGeometry(2000,2000),new THREE.MeshStandardMaterial({color:'#4c8990',roughness:.36,metalness:.04})); ocean.rotation.x=-Math.PI/2; ocean.position.y=-3.7; scene.add(ocean);
const beach=new THREE.Mesh(new THREE.RingGeometry(110,139,112),new THREE.MeshStandardMaterial({color:'#c6b47c',roughness:1,side:THREE.DoubleSide})); beach.rotation.x=-Math.PI/2; beach.position.y=-2.85; scene.add(beach);

function treeAt(x,z,scale=1){
  const y=heightAt(x,z); if(y<-.1)return;
  const g=new THREE.Group();g.position.set(x,y,z);g.scale.setScalar(scale);
  const trunk=new THREE.Mesh(new THREE.CylinderGeometry(.13,.21,2.1,6),mat('#6a503b'));trunk.position.y=1.05;trunk.castShadow=true;g.add(trunk);
  const tone=Math.random(); const leaves=mat(tone>.5?'#52784f':tone>.25?'#5c8053':'#68885a');
  const crown=new THREE.Mesh(new THREE.IcosahedronGeometry(1.35,1),leaves); crown.position.y=2.55;crown.scale.set(.92,1.14,.91);crown.castShadow=true;g.add(crown);
  const crown2=new THREE.Mesh(new THREE.IcosahedronGeometry(.9,0),leaves);crown2.position.set(.5,3.15,.18);crown2.castShadow=true;g.add(crown2);
  world.add(g);
}
function rockAt(x,z,s=1){const y=heightAt(x,z);const m=new THREE.Mesh(new THREE.DodecahedronGeometry(s,0),mat('#777f70'));m.position.set(x,y+s*.42,z);m.scale.set(1,.72,.84);m.rotation.set(rand(0,1),rand(0,5),rand(0,1));m.castShadow=true;m.receiveShadow=true;world.add(m)}
// Organic groves leave room around trails and landmarks.
for(let i=0;i<430;i++){
  const x=rand(-112,112),z=rand(-112,112),r=Math.hypot(x,z);
  if(r>107||heightAt(x,z)<.2)continue;
  const trail=Math.abs(z-(.32*x+12));
  const meadow=Math.hypot(x+5,z+8);
  if(trail<5.4||meadow<17)continue;
  if(Math.random()<.78)treeAt(x,z,rand(.65,1.28));
}
for(let i=0;i<90;i++){
  const a=rand(0,Math.PI*2),r=rand(20,103),x=Math.cos(a)*r,z=Math.sin(a)*r;
  if(heightAt(x,z)>.2 && Math.abs(z-(.32*x+12))>4)rockAt(x,z,rand(.25,.9));
}

// Soft trail winding across the island.
const trailPoints=[];
for(let i=0;i<=70;i++){const t=i/70,x=-94+t*188,z=.32*x+12+Math.sin(t*Math.PI*2)*4;trailPoints.push(new THREE.Vector3(x,heightAt(x,z)+.1,z));}
const trail=new THREE.Mesh(new THREE.TubeGeometry(new THREE.CatmullRomCurve3(trailPoints),190,2.1,7,false),mat('#b4a779'));trail.position.y=.02;world.add(trail);

function makeCabin(x,z){
  const y=heightAt(x,z);const group=new THREE.Group();group.position.set(x,y,z);
  const base=new THREE.Mesh(new THREE.BoxGeometry(8,4.2,6),mat('#99704e'));base.position.y=2.1;base.castShadow=true;base.receiveShadow=true;group.add(base);
  const roof=new THREE.Mesh(new THREE.ConeGeometry(5.5,3,4),mat('#554d3e'));roof.position.y=5.5;roof.rotation.y=Math.PI/4;roof.scale.z=.82;roof.castShadow=true;group.add(roof);
  const door=new THREE.Mesh(new THREE.BoxGeometry(1.2,2.3,.12),mat('#4a4034'));door.position.set(0,1.15,3.06);group.add(door);
  for(const xw of [-2.4,2.4]){const win=new THREE.Mesh(new THREE.BoxGeometry(1.15,1.05,.14),mat('#afd0bd'));win.position.set(xw,2.45,3.08);group.add(win)}
  world.add(group);
}
makeCabin(-20,-20);

// Landmark rings and small floral accents.
const landmarkData=[
 {name:'SUNMEADOW',detail:'The open country',x:0,z:0},
 {name:'OLD PINE LOOKOUT',detail:'A quiet view above the trees',x:-48,z:-34},
 {name:'WAYFARER CABIN',detail:'A shelter on the old trail',x:-20,z:-20},
 {name:'MISTY HOLLOW',detail:'Where the valley breathes',x:14,z:18},
 {name:'SILVERGLASS SHORE',detail:'The island edge',x:83,z:16},
 {name:'FERNGLEN',detail:'A green pocket of quiet',x:39,z:55},
 {name:'NORTHWIND RIDGE',detail:'High ground, wide sky',x:-4,z:-81}
];
function markerRing(x,z,color='#eed789'){
 const y=heightAt(x,z);const ring=new THREE.Mesh(new THREE.TorusGeometry(1.3,.09,8,24),new THREE.MeshStandardMaterial({color,emissive:color,emissiveIntensity:.35,roughness:.36}));ring.position.set(x,y+1.25,z);ring.rotation.x=Math.PI/2;ring.castShadow=true;world.add(ring);
 const crystal=new THREE.Mesh(new THREE.OctahedronGeometry(.65,0),new THREE.MeshStandardMaterial({color:'#fff1b1',emissive:'#d6b958',emissiveIntensity:.75,roughness:.22,metalness:.1}));crystal.position.set(x,y+2.25,z);crystal.castShadow=true;world.add(crystal);
 const glow=new THREE.PointLight('#f0d783',1.8,8,2);glow.position.set(x,y+2,z);world.add(glow);
 return {x,z,ring,crystal,glow,collected:false};
}
const waypoints=[[-60,-24],[-42,-51],[-24,-4],[-3,16],[22,32],[44,54],[70,20],[10,-70]];
const collectibles=waypoints.map(([x,z])=>markerRing(x,z));
for(let i=0;i<150;i++){
 const x=rand(-94,94),z=rand(-94,94);if(heightAt(x,z)<.4||Math.hypot(x,z)<15)continue;
 const flower=new THREE.Mesh(new THREE.SphereGeometry(.09,6,6),mat(Math.random()>.5?'#e4d58c':'#d7c4a0'));flower.position.set(x,heightAt(x,z)+.16,z);world.add(flower);
}

