 const banner=$('#mode-banner');banner.classList.add('show');setTimeout(()=>banner.classList.remove('show'),2500);
}
function pauseGame(){if(!state.playing)return;state.paused=!state.paused;pausePanel.classList.toggle('visible',state.paused)}
$('#play-button').addEventListener('click',startGame);$('#resume-button').addEventListener('click',()=>{state.paused=false;pausePanel.classList.remove('visible')});$('#pause-button').addEventListener('click',pauseGame);$('#home-button').addEventListener('click',()=>state.playing?pauseGame():overlay.classList.remove('hidden'));$('#menu-button').addEventListener('click',()=>{state.paused=false;state.playing=false;pausePanel.classList.remove('visible');overlay.classList.remove('hidden');$('#pause-button').style.display='none'});
$('#map-toggle').addEventListener('click',()=>{state.hideMap=!state.hideMap;$('.hud-right').style.opacity=state.hideMap?'0':'1';$('.hud-right').style.pointerEvents=state.hideMap?'none':'auto'});

